import sys

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    students = lines[1:n+1]
    pseudonyms = lines[n+1:2*n+1]

    if n == 0:
        return "0\n"

    # Compute LCP for each pair
    lcp = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            s = students[i]
            p = pseudonyms[j]
            length = 0
            for c in range(min(len(s), len(p))):
                if s[c] == p[c]:
                    length += 1
                else:
                    break
            lcp[i][j] = length

    # Greedy matching with maximum weight
    # Sort all possible pairs by LCP value
    pairs = []
    for i in range(n):
        for j in range(n):
            pairs.append((lcp[i][j], i, j))

    pairs.sort(key=lambda x: -x[0])

    # Try greedy matching, then iterate to improve
    result = [-1] * n
    used_student = [False] * n
    used_pseudonym = [False] * n
    score = 0

    max_match = 0
    for grad, si, pi in pairs:
        if max_match > min(n, 1000):
            break
        if not used_student[si] and not used_pseudonym[pi]:
            used_student[si] = True
            used_pseudonym[pi] = True
            result[si] = pi
            score += grad
            max_match += 1

    # ...output results
    lines_out = []
    for i in range(n):
        if result[i] != -1:
            lines_out.append(f"{i+1} {result[i]+1}")

    return f"{score}\n" + "\n".join(lines_out)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    g = [0] * max(a + 1)

    if k % 2 == 1:  # k is odd
        for i in range(1, max(a) + 1):
            if i % 2 == 1:
                g[i] = 1
            else:
                g[i] = 0
    else:  # k is even
        SV = set()
        for i in range(1, max(a) + 1):
            SV.discard(g[i - 1])
            g[i] = 0
            for j in SV:
                g[i] ^= j
            if i % 2 == 0:
                SV.add(0)

    xor_sum = 0
    for x in a:
        xor_sum ^= g[x]

    return "Kevin\n" if xor_sum != 0 else "Nicky\n"

