    parities = list(map(int, lines[m + 1].split()))

    # If no edges
    if m == 0:
        if all(p == 0 for p in parities):
            return "0\n"
        return "-1\n"

    # Count odd parity vertices
    odd_count = sum(parities)
    if odd_count % 2 != 0:
        return "-1\n"

    if odd_count == 0:
        return "0\n"

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                component.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(component)

    # Build path
    result = []

    for component in components:
        odd_vertices = [v for v in component if parities[v-1] == 1]

        if len(odd_vertices) == 0:
            # All even parity needed
            # Visit each node an even number of times
            # Build cycle-like path
            if len(component) >= 2:
                path = component.copy()
                # Each internal node gets visited once as intermediate
                # But we need even visits for all
                # Simple: visit first, then traverse back
                result.append(path[0])
                for i in range(len(path) - 1):
                    result.append(path[i])
                    result.append(path[i + 1])
            else:
                # Single node with even parity
                pass

        elif len(odd_vertices) == 2:
            # Path between two odd vertices
            start, end = odd_vertices

            # BFS to find path
            parent = {start: None}
            queue = deque([start])
            found = False

            while queue and not found:
                u = queue.popleft()
                if u == end:
                    found = True
                    break
                for v in adj[u]:
                    if v not in parent:
                        parent[v] = u
                        queue.append(v)

            if found:
                path = []
                curr = end
                while curr is not None:
                    path.append(curr)
                    curr = parent[curr]
                path.reverse()
                result.extend(path)
            else:
                # Unreachable in component (shouldn't happen for connected)
                return "-1\n"

        elif len(odd_vertices) > 2 and len(odd_vertices) % 2 == 0:
            # Need to handle more complex case
            # Pair up odd vertices and build paths between pairs
            num_pairs = len(odd_vertices) // 2

            for pair in range(num_pairs):
                start, end = odd_vertices[2 * pair], odd_vertices[2 * pair + 1]

                parent = {start: None}
                queue = deque([start])
                found = False

                while queue and not found:
                    u = queue.popleft()
                    if u == end:
