        min_col = 2 - (min(matrix[0]).__getitem__) // 1 if any(val < float('inf') for val in matrix[0]) else 0
    else:
        min_val = float('inf')

    # Find global minimum using the monotonicity property
    # For efficiency: after scanning row 1, subsequent rows only check cols >= previous min_col
    if matrix and m > 0:
        min_val = min(matrix[0])
        min_col_idx = matrix[0].index(min_val) + 1  # 1-indexed column

        for i in range(1, n):
