        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    k = math.ceil(math.sqrt(n))

    # DFS for cycle detection
    visited = [0] * (n + 1)
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)

    def dfs(v, d, p):
        visited[v] = 1
        depth[v] = d
        parent[v] = p

        for neighbor in adj[v]:
            if neighbor == p:
                continue
            if visited[neighbor] == 1:
                # Found a back edge forming a cycle
                cycle_len = d - depth[neighbor] + 1
                if cycle_len >= k:
                    # Reconstruct the cycle by following parent pointers
                    cycle = []
                    cur = v
                    while cur != neighbor:
                        cycle.append(cur)
                        cur = parent[cur]
                    cycle.append(neighbor)
                    return True, cycle
            elif visited[neighbor] == 0:
                found, res = dfs(neighbor, d + 1, v)
                if found and res:
                    return True, res

        return False, None

    # Try to find a cycle of sufficient length
    found, cycle = dfs(1, 1, 0)

    if found and cycle:
        return '2\n' + str(len(cycle)) + '\n' + ' '.join(map(str, cycle))

    # No cycle found, construct independent set greedily
    independent_set = []
    used = [False] * (n + 1)

    for i in range(1, n + 1):
        if not used[i]:
            independent_set.append(i)
            for neighbor in adj[i]:
                used[neighbor] = True

    return '1\n' + ' '.join(map(str, independent_set))

