def factorize(n):
    """Return list of prime factors of n"""
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def can_eliminate_pm(a_i, p, k):
    """Check if judge with uncertainty a_i can eliminate factor p"""
    vp = 0
    temp = a_i
    while temp % p == 0:
        vp += 1
        temp //= p

    # If p^vp is much larger than k, we can't eliminate p completely
    pp = p ** vp
    return pp <= k and vp >= 1

