    ux = ((p1[0]**2 + p1[1]**2 + p1[2]**2) * (p2[1] - p3[1]) + 
          (p2[0]**2 + p2[1]**2 + p2[2]**2) * (p3[1] - p1[1]) + 
          (p3[0]**2 + p3[1]**2 + p3[2]**2) * (p1[1] - p2[1])) / d
    uy = ((p1[0]**2 + p1[1]**2 + p1[2]**2) * (p3[0] - p2[0]) + 
          (p2[0]**2 + p2[1]**2 + p2[2]**2) * (p1[0] - p3[0]) + 
          (p3[0]**2 + p3[1]**2 + p3[2]**2) * (p2[0] - p1[0])) / d
    uz = ((p1[0]**2 + p1[1]**2 + p1[2]**2) * (p2[2] - p3[2]) + 
