    Find the moment when the last hole disappears as n circles grow.
    A hole exists when 3+ circles mutually intersect and enclose a white region.
    The last hole disappears at max circumradius among all valid triples.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    circles = []
    for i in range(1, n + 1):
        x, y = map(float, lines[i].split())
        circles.append((float(x), float(y)))

    if n < 3:
        return "-1\n"

    def pairwise_dist(A, B):
        return math.hypot(A[0] - B[0], A[1] - B[1])

    def circumradius(A, B, C):
        """Compute circumradius of triangle formed by three points."""
        a = pairwise_dist(B, C)
        b = pairwise_dist(A, C)
        c = pairwise_dist(A, B)

        # Check for degenerate triangle
        if a + b <= c or a + c <= b or b + c <= a:
            return float('inf')  # Not a valid triangle

        # Heron's formula: area = sqrt(s*(s-a)*(s-b)*(s-c))
        s = (a + b + c) / 2
        if s <= 0:
            return float('inf')

        area_sq = s * (s - a) * (s - b) * (s - c)
        if area_sq <= 0:
            return float('inf')  # Degenerate (collinear)

        area = math.sqrt(area_sq)
        if area < 1e-12:
            return float('inf')

        return (a * b * c) / (4 * area)

    max_circumradius = 0.0
    found_valid = False

    # Check all triples
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                r = circumradius(circles[i], circles[j], circles[k])
                if r < float('inf') and r > 1e-12:
                    found_valid = True
                    max_circumradius = max(max_circumradius, r)

    if not found_valid:
        return "-1\n"

    return f"{max_circumradius:.6f}\n"


